package com.database.societyproject.finance.service;
import com.database.societyproject.common.exception.*;
import com.database.societyproject.finance.dto.*;
import com.database.societyproject.finance.entity.*;
import com.database.societyproject.finance.repository.GatewayPaymentOrderRepository;
import com.database.societyproject.occupancy.repository.FlatOccupancyRepository;
import com.database.societyproject.resident.repository.ResidentRepository;
import com.database.societyproject.security.service.SocietyAuthorizationService;
import com.fasterxml.jackson.databind.*;
import java.math.*; import java.net.*; import java.net.http.*; import java.nio.charset.StandardCharsets; import java.time.LocalDate; import java.util.*; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;

@Service @Transactional public class RazorpayPaymentService {
 private final GatewayPaymentOrderRepository orders; private final MaintenanceBillService bills; private final PaymentService payments; private final ObjectMapper mapper; private final SocietyAuthorizationService authorization; private final ResidentRepository residents; private final FlatOccupancyRepository occupancies; private final String keyId, keySecret, webhookSecret;
 public RazorpayPaymentService(GatewayPaymentOrderRepository o, MaintenanceBillService b, PaymentService p, ObjectMapper m, SocietyAuthorizationService a, ResidentRepository r, FlatOccupancyRepository oc, @Value("${app.razorpay.key-id}") String i, @Value("${app.razorpay.key-secret}") String s, @Value("${app.razorpay.webhook-secret}") String w){orders=o;bills=b;payments=p;mapper=m;authorization=a;residents=r;occupancies=oc;keyId=i;keySecret=s;webhookSecret=w;}
 public GatewayOrderResponse create(GatewayOrderRequest r){ requireKeys(); MaintenanceBill bill=bills.findEntity(r.billId()); requireBillAccess(bill); BigDecimal due=bill.getAmount().subtract(bill.getPaidAmount()); if(due.signum()<=0)throw new InvalidRequestException("This bill is already fully paid"); long paise=due.movePointRight(2).longValueExact(); String receipt="bill_"+bill.getId()+"_"+UUID.randomUUID().toString().substring(0,8); try { String json=mapper.writeValueAsString(Map.of("amount",paise,"currency","INR","receipt",receipt)); HttpRequest q=HttpRequest.newBuilder(URI.create("https://api.razorpay.com/v1/orders")).header("Content-Type","application/json").header("Authorization","Basic "+Base64.getEncoder().encodeToString((keyId+":"+keySecret).getBytes(StandardCharsets.UTF_8))).POST(HttpRequest.BodyPublishers.ofString(json)).build(); HttpResponse<String> response=HttpClient.newHttpClient().send(q,HttpResponse.BodyHandlers.ofString()); if(response.statusCode()/100!=2)throw new InvalidRequestException("Razorpay rejected order creation (HTTP "+response.statusCode()+"). Check that the Test Mode Key ID and Key Secret belong to the same Razorpay account."); String orderId=mapper.readTree(response.body()).path("id").asText(); if(orderId.isBlank())throw new InvalidRequestException("Razorpay did not return an order id"); GatewayPaymentOrder order=new GatewayPaymentOrder(); order.setBill(bill);order.setRazorpayOrderId(orderId);order.setAmountPaise(paise);orders.save(order); return new GatewayOrderResponse(order.getId(),bill.getId(),orderId,paise,"INR",keyId); }catch(InvalidRequestException e){throw e;}catch(Exception e){throw new InvalidRequestException("Unable to contact Razorpay. Check your network connection and Test Mode credentials.");}}
 public PaymentResponse verify(RazorpayVerificationRequest r){ GatewayPaymentOrder order=find(r.razorpayOrderId()); requireBillAccess(order.getBill()); if(order.getStatus()==GatewayOrderStatus.SUCCESS)return paymentResponse(order); if(!constantTime(hmac(order.getRazorpayOrderId()+"|"+r.razorpayPaymentId(),keySecret),r.razorpaySignature()))throw new InvalidRequestException("Razorpay payment signature is invalid"); return complete(order,r.razorpayPaymentId()); }
 public void webhook(String raw,String signature){ requireWebhook(); if(!constantTime(hmac(raw,webhookSecret),signature))throw new InvalidRequestException("Razorpay webhook signature is invalid"); try { JsonNode root=mapper.readTree(raw); if(!"payment.captured".equals(root.path("event").asText()))return; JsonNode payment=root.path("payload").path("payment").path("entity"); String orderId=payment.path("order_id").asText(); String paymentId=payment.path("id").asText(); if(!orderId.isBlank()&&!paymentId.isBlank()) { GatewayPaymentOrder order=find(orderId); if(order.getStatus()!=GatewayOrderStatus.SUCCESS)complete(order,paymentId); }}catch(InvalidRequestException e){throw e;}catch(Exception e){throw new InvalidRequestException("Invalid Razorpay webhook payload");} }
 private PaymentResponse complete(GatewayPaymentOrder o,String paymentId){ o.setStatus(GatewayOrderStatus.SUCCESS);o.setRazorpayPaymentId(paymentId); return payments.create(new PaymentRequest(o.getBill().getId(),BigDecimal.valueOf(o.getAmountPaise(),2),LocalDate.now(),PaymentMethod.ONLINE,paymentId,"Verified Razorpay payment")); }
 private PaymentResponse paymentResponse(GatewayPaymentOrder o){ return payments.findByBillId(o.getBill().getId()).stream().filter(p->o.getRazorpayPaymentId().equals(p.referenceNumber())).findFirst().orElseThrow(()->new InvalidRequestException("Verified payment record is missing")); }
 private void requireBillAccess(MaintenanceBill bill){ if(bill.getStatus()==BillStatus.VOID) throw new InvalidRequestException("This bill has been voided and cannot be paid"); Long societyId=bill.getFlat().getBlock().getSociety().getId(); if(authorization.canManage(societyId)) return; var resident=residents.findByUserId(authorization.currentUserId()).orElseThrow(()->new org.springframework.security.access.AccessDeniedException("Only the resident of this flat may pay this bill")); if(!occupancies.existsByFlatIdAndResidentIdAndActiveTrue(bill.getFlat().getId(),resident.getId())) throw new org.springframework.security.access.AccessDeniedException("Only the resident of this flat may pay this bill"); }
 private GatewayPaymentOrder find(String id){return orders.findByRazorpayOrderId(id).orElseThrow(()->new InvalidRequestException("Razorpay order was not found"));} private void requireKeys(){if(keyId.isBlank()||keySecret.isBlank())throw new InvalidRequestException("Razorpay test keys are not configured");} private void requireWebhook(){if(webhookSecret.isBlank())throw new InvalidRequestException("Razorpay webhook secret is not configured");} private String hmac(String value,String secret){try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return HexFormat.of().formatHex(mac.doFinal(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} private boolean constantTime(String a,String b){return java.security.MessageDigest.isEqual(a.getBytes(StandardCharsets.UTF_8),b.getBytes(StandardCharsets.UTF_8));}
}
